pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64) -> f64 {
    let mut score = bin_residual as f64;

    // Key insights:
    // 1. Dead space: If bin_residual < 10, no future item can ever fit! Penalize heavily (+90.0 or more).
    if bin_residual < 10 {
        score += (90.0 * (10 - bin_residual) as f64).max(50.0);
    }

    // 2. Exact fit: If bin_residual == 0, bin is perfectly closed. Reward (-50.0).
    if bin_residual == 0 {
        score -= 50.0;
    }

    score
}

